// Enforce: session must be a valid initialized pointer (runtime supplies persistent LIBSSH2_SESSION*)
// Prepare input payload to sign
std::string data_str = FUZZ_PARAM_STR();
const unsigned char *data = reinterpret_cast<const unsigned char *>(data_str.data());
size_t data_len = data_str.size();
if (!data || data_len == 0) { FUZZ_BAIL(); }

