void *abstract = abstract_storage ? *abstract_storage : NULL;

int rc = libssh2_sign_sk(session, &sig_local, &sig_len_local, data, data_len, abstract_storage ? abstract_storage : NULL);
// If the call failed, bail to keep invariants (no outputs on failure)
if (rc != 0) { FUZZ_BAIL(); }

// Success: record the allocated signature buffer for later libssh2_free(session, ...)
// Track ownership and size for safety.
void *sig_ptr = static_cast<void *>(sig_local);
FUZZ_SET_ATTR_PTR(sig_ptr, "libssh2_alloc_owner", session);
FUZZ_SET_ATTR_INT(sig_ptr, "libssh2_alloc_size", (int)sig_len_local);
// Maintain a per-session allocation refcount to prevent freeing the session while outstanding allocations exist
FUZZ_SET_ATTR_INT(session, "alloc_count", FUZZ_GET_ATTR_INT(session, "alloc_count") + 1);

// Validation: sig_ptr must be non-null and length > 0
FUZZ_ASSERT(sig_ptr != NULL && sig_len_local > 0, "libssh2_sign_sk returned invalid signature");
// Outputs: session (still owned by runtime), sig_ptr (to be freed later via libssh2_free)
// End stub: validated and returned persistent outputs

