import os
import random
import string
from typing import List

# Generator for a passphrase string suitable for libssh2 private key decryption.
# The target stubs consume FUZZ_PARAM_STR() for usernames, hostnames, key file data, and
# optionally passphrases. Our focus data type is a passphrase string. We therefore
# produce a bytes buffer that, when used to back FUZZ_PARAM_STR or FUZZ_PARAM_FILENAME
# sources, is an interesting, valid passphrase covering diverse character classes and lengths.
#
# Strategy:
# - Generate passphrases of varying lengths (including empty, short, medium, long up to ~1KB).
# - Include diverse character sets: ASCII printable, spaces, punctuation, quotes, backslashes,
#   unicode UTF-8 sequences, null-free (C strings in fuzzers often accept embedded NUL poorly),
#   but we will avoid NUL bytes to keep it safe as C strings.
# - Include formats commonly seen in real-world passphrases (words with separators), as well as
#   high-entropy random base64-like strings, hex-like, and phrase with emojis and non-ASCII.
# - Ensure total buffer <= 4096 bytes.
#
# Note: We return a bytes object. No file I/O or external deps.

ASCII_WORDS = [
    "correct", "horse", "battery", "staple", "admin", "root", "user",
    "libssh2", "ssh", "key", "pass", "phrase", "secure", "token",
    "fido", "webauthn", "u2f", "auth", "rsa", "ed25519", "ecdsa",
    "private", "public", "session", "host"
]

SYMBOLS = "!@#$%^&*()-_=+[]{}|;:'\",.<>/?`~"
BASE64CHARS = string.ascii_letters + string.digits + "+/"
HEXCHARS = string.hexdigits.lower()

UNICODE_FRAGMENTS = [
    "密码", "пароль", "كلمةالسر", "सुरक्षित", "🔐", "🔑", "パスワード", "암호",
    "ключ", "סיסמה", "mötör", "naïve", "résumé", "Café"
]

def _rand_choice(rng: random.Random, seq: List[str]):
    return seq[rng.randrange(0, len(seq))]

def _rand_base64(rng: random.Random, length: int) -> str:
    return ''.join(rng.choice(BASE64CHARS) for _ in range(length))

def _rand_hex(rng: random.Random, length: int) -> str:
    return ''.join(rng.choice(HEXCHARS[:16]) for _ in range(length))

def _rand_symbols(rng: random.Random, length: int) -> str:
    pool = SYMBOLS + " "
    return ''.join(rng.choice(pool) for _ in range(length))

def _rand_printable(rng: random.Random, length: int) -> str:
    pool = string.ascii_letters + string.digits + SYMBOLS + " "
    return ''.join(rng.choice(pool) for _ in range(length))

def _word_phrase(rng: random.Random, words_min=2, words_max=6) -> str:
    n = rng.randint(words_min, words_max)
    words = [_rand_choice(rng, ASCII_WORDS) for _ in range(n)]
    sep = rng.choice([" ", "-", "_", ".", ":", "/", "|"])
    phrase = sep.join(words)
    # sprinkle digits/symbols at random positions
    if rng.random() < 0.8:
        insert_chars = rng.choice([_rand_hex(rng, rng.randint(2, 6)), _rand_symbols(rng, rng.randint(1, 3))])
        pos = rng.randint(0, len(phrase))
        phrase = phrase[:pos] + insert_chars + phrase[pos:]
    # random case toggles
    if rng.random() < 0.5:
        phrase = ''.join(c.upper() if rng.random() < 0.5 else c.lower() for c in phrase)
    return phrase

def _unicode_phrase(rng: random.Random) -> str:
    # Mix ASCII words with unicode fragments
    parts = []
    total_parts = rng.randint(2, 6)
    for _ in range(total_parts):
        if rng.random() < 0.5:
            parts.append(_rand_choice(rng, ASCII_WORDS))
        else:
            parts.append(_rand_choice(rng, UNICODE_FRAGMENTS))
    sep = rng.choice([" ", "-", "_", "·", "—"])
    s = sep.join(parts)
    if rng.random() < 0.6:
        s += rng.choice(["!", "?", "#", "✨", "✅"])
    return s

def _pattern_variant(rng: random.Random) -> str:
    # Choose among several structured patterns
    choice = rng.randint(0, 6)
    if choice == 0:
        # base64-like with padding
        l = rng.randint(8, 64)
        s = _rand_base64(rng, l)
        if l % 4 != 0:
            s += "=" * (4 - (l % 4))
        return s
    if choice == 1:
        # hex block groups
        groups = rng.randint(2, 8)
        glen = rng.choice([4, 8, 16])
        return '-'.join(_rand_hex(rng, glen) for _ in range(groups))
    if choice == 2:
        # printable random
        return _rand_printable(rng, rng.randint(4, 48))
    if choice == 3:
        # words phrase
        return _word_phrase(rng)
    if choice == 4:
        # unicode phrase
        return _unicode_phrase(rng)
    if choice == 5:
        # symbol heavy
        core = _rand_symbols(rng, rng.randint(4, 24))
        return core + _rand_printable(rng, rng.randint(0, 8))
    # mixed case with digits at ends
    middle = _word_phrase(rng)
    prefix = _rand_hex(rng, rng.randint(1, 4))
    suffix = _rand_hex(rng, rng.randint(1, 4))
    return prefix + middle + suffix

def _edge_case_variant(rng: random.Random) -> str:
    # Specific edge cases: empty, single-char, space-only, long repeated, quotes/backslashes
    which = rng.randint(0, 7)
    if which == 0:
        return ""  # empty passphrase
    if which == 1:
        return rng.choice([" ", "\t", "\r", "\n"]).replace("\n", " ")  # avoid embedded NUL; keep safe spaces
    if which == 2:
        cands = ["'", '"', "\\", ":", ";", "#", "$", " "]
        return rng.choice(cands)
    if which == 3:
        ch = rng.choice(["a", "A", "1", "*", " "])
        return ch * rng.randint(2, 64)
    if which == 4:
        # Quotes and escapes
        return "\"Quoted passphrase with spaces\" \\and\\ symbols#@!"
    if which == 5:
        # Looks like environment variable
        return "${SSH_PASSPHRASE}_" + _rand_hex(rng, 6)
    if which == 6:
        # Looks like a common phrase with year and punctuation
        return "Summer" + str(rng.randint(1990, 2050)) + "!" + _rand_symbols(rng, 2)
    # include some unicode edge
    return "пароль:" + _rand_hex(rng, 4)

def _compose_final(rng: random.Random) -> str:
    # Decide on overall length target
    target_len = rng.choice([0, 1, 2, 4, 8, 12, 16, 24, 32, 48, 64, 96, 128, 256, 512, 1024])

    # Start with a base variant
    s = _pattern_variant(rng) if rng.random() < 0.8 else _edge_case_variant(rng)

    # Optionally concatenate more segments for longer passphrases
    while len(s.encode('utf-8')) < target_len and rng.random() < 0.7:
        sep = rng.choice([" ", "-", "_", ":", "/", "|", "."])
        nxt = _pattern_variant(rng) if rng.random() < 0.75 else _edge_case_variant(rng)
        s = s + sep + nxt
        if len(s) > 1200:  # cap logical size
            break

    # Trim to at most 2048 bytes in UTF-8
    b = s.encode('utf-8', errors='ignore')
    if len(b) > 2048:
        b = b[:2048]
        # avoid cutting mid-UTF8 by decoding with ignore, then re-encode
        s = b.decode('utf-8', errors='ignore')
        b = s.encode('utf-8')
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # With some probability, return a curated extreme edge case directly
    if rng.random() < 0.1:
        curated = [
            b"",  # empty
            b" ",  # single space
            b"password",
            b"toomanyspaces   inside   here",
            b"correct horse battery staple",
            b"P@ssw0rd!",
            "🔐 secure passphrase 🔑".encode('utf-8'),
            _rand_base64(rng, 48).encode('ascii') + b"==",
        ]
        return rng.choice(curated)

    s = _compose_final(rng)

    # Ensure no NUL bytes (C-string safety). If any sneaked in, replace with 'X'.
    b = s.encode('utf-8', errors='ignore').replace(b"\x00", b"X")

    # Final safety cap
    if len(b) > 4096:
        b = b[:4096]

    return b
